def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.163.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.162.0"' not in init:
        sys.exit("ABORT: not at v3.162.0.")
    for k in ("banking", "ar_ap_chair"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("ACC3", LESSONS_A3, QUESTIONS_A3, 9) + _validate("ACC4", LESSONS_A4, QUESTIONS_A4, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("ACC 3", LESSONS_A3, QUESTIONS_A3, "banking",
         "Banking in ZhiftERP: the Bank-type ledger account, Bank Account record, and Mode of Payment mapping per real account; Bank Statement Import and matching in the Bank Reconciliation Tool with Create Voucher for bank-side items; the Bank Reconciliation Statement report; age limits for uncleared items; the imprest float and its invariant; the four-link cash-up chain recorded through Internal Transfers; and bank governance — prepare/release, masters-not-messages, mandate reviews, and the calendar."),
        ("ACC 4", LESSONS_A4, QUESTIONS_A4, "ar_ap_chair",
         "Receivables and payables from the accounts side: the monthly tie check against the Accounts Receivable and Payable reports; clearing floating items in Payment Reconciliation; advances captured against orders and consumed through the invoice's Advances section under the never-net rule; provisioning by aging matrix with the two-signature write-off workflow and recoveries; Process Statement Of Accounts and the supplier-statement mirror; per-invoice openings with the Opening Invoice Creation Tool; and the seven-step month-end routine."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.162.0"', '"3.163.0"'))
    print("  data: ACCOUNTS 3 + 4 lessons + banks REPLACED (style v3, product-first)")
    print("wrote __version__ -> 3.163.0")


if __name__ == "__main__":
    main()
